glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform Factor {
    float angle;
    float offset;
    float uvRatio;
};
  vec3 rgbtohsv(vec3 rgb)
  {
  float R = rgb.x;
  float G = rgb.y;
  float B = rgb.z;
  vec3 hsv;
  float max1 = max(R, max(G, B));
  float min1 = min(R, min(G, B));
  if (R == max1)
  {
  if(max1 == min1)
  {
  hsv.x = 0.0;
  }
  else
  {
  hsv.x = (G - B) / (max1 - min1);
  }
  }
  if (G == max1)
  {
  if(max1 == min1)
  {
  hsv.x = 2.0;
  }
  else
  {
  hsv.x = 2.0 + (B - R) / (max1 - min1);
  }
  }
  if (B == max1)
  {
  if(max1 == min1)
  {
  hsv.x = 4.0;
  }
  else
  {
  hsv.x = 4.0 + (R - G) / (max1 - min1);
  }
  }
  hsv.x = hsv.x * 60.0;
  if (hsv.x < 0.0)
  {
  hsv.x = hsv.x + 360.0;
  }
  hsv.z = max1;
  if(max1 == 0.0)
  {
  hsv.y = 0.0;
  }
  else
  {
  hsv.y = (max1 - min1) / max1;
  }
  return hsv;
  }
  vec3 hsvtorgb(vec3 hsv)
  {
  float R;
  float G;
  float B;
  if (hsv.y == 0.0)
  {
  R = G = B = hsv.z;
  }
  else
  {
  hsv.x = hsv.x / 60.0;
  int i = int(hsv.x);
  float f = hsv.x - float(i);
  float a = hsv.z * (1.0 - hsv.y);
  float b = hsv.z * (1.0 - hsv.y * f);
  float c = hsv.z * (1.0 - hsv.y * (1.0 - f));
  if (i == 0)
  {
  R = hsv.z;
  G = c;
  B = a;
  }
  else if (i == 1)
  {
  R = b;
  G = hsv.z;
  B = a;
  }
  else if (i == 2)
  {
  R = a;
  G = hsv.z;
  B = c;
  }
  else if (i == 3)
  {
  R = a;
  G = b;
  B = hsv.z;
  }
  else if (i == 4)
  {
  R = c;
  G = a;
  B = hsv.z;
  }
  else
  {
  R = hsv.z;
  G = a;
  B = b;
  }
  }
  return vec3(R, G, B);
  }
uniform Constant {
    vec4 beginColor;
    vec4 middleColor;
};
uniform Properties {
    float u_saturation;
    float u_brightness;
  };
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  o *= v_color;
  ALPHA_TEST(o);
  float angleInRadians = radians(angle);
  float ratio = clamp((v_uv0.y * cos(angleInRadians) + v_uv0.x * sin(angleInRadians) + offset) * uvRatio, 0.0, 1.0);
  float beginRatio = 1.0 - ratio;
  float endRatio = ratio;
  vec4 color = vec4(1, 1, 1, 1);;
  if(beginRatio > 0.5) {
        color = vec4(
                    o.r * (beginColor.r * beginRatio + middleColor.r * endRatio),
                    o.g * (beginColor.g * beginRatio + middleColor.g * endRatio),
                    o.b * (beginColor.b * beginRatio + middleColor.b * endRatio),
                    o.a * (beginColor.a * beginRatio + middleColor.a * endRatio)
                  );
  }else {
        color = vec4(
                            o.r * (middleColor.r * beginRatio + beginColor.r * endRatio),
                            o.g * (middleColor.g * beginRatio + beginColor.g * endRatio),
                            o.b * (middleColor.b * beginRatio + beginColor.b * endRatio),
                            o.a * (middleColor.a * beginRatio + beginColor.a * endRatio)
                          );
  }
      vec3 hsv;
      hsv.xyz = rgbtohsv(color.xyz);
      hsv.x = mod(hsv.x, 360.0);
      hsv.y *= u_saturation;
      hsv.z *= u_brightness;
      vec3 f_color = hsvtorgb(hsv);
      gl_FragColor = v_color * vec4(f_color, color.a);
}

